import{_ as a,o as r,c as t,a0 as s}from"./chunks/framework.BPYRhTv9.js";const p=JSON.parse('{"title":"Limitations","description":"","frontmatter":{"title":"Limitations"},"headers":[],"relativePath":"reference/limitations.md","filePath":"reference/limitations.md"}'),i={name:"reference/limitations.md"};function o(n,e,l,d,c,u){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h1><p><em>Last updated: Jul 17, 2026</em></p><p>These are constraints we chose on purpose. They are not bugs — they are product decisions listed here so you understand what we have prioritized.</p><h3 id="daily-caps-keep-the-service-sustainable" tabindex="-1">Daily caps keep the service sustainable <a class="header-anchor" href="#daily-caps-keep-the-service-sustainable" aria-label="Permalink to &quot;Daily caps keep the service sustainable&quot;">​</a></h3><p>Free tier: 5 recordings per day, 1 tone rewrite per tone per day, 15-second max recording length, 75 seconds cumulative audio per day. Pro raises recordings to 50 per day and cumulative audio to 900 seconds (15 minutes), and makes rewrites unlimited.</p><ul><li><strong>Sustainability:</strong> STT costs per audio second and LLM rewrite costs per call both scale with usage. Caps keep infrastructure bills predictable.</li><li><strong>Abuse prevention:</strong> Scripts that create hundreds of cards per minute for SEO spam farms or scrape rewritten phrases for training datasets are blocked by daily limits.</li><li><strong>Pro accounts</strong> provide a verified payment method that can be revoked if abuse is detected.</li><li>The counter color degrades visually: gray (0–119 used) → yellow (120–150) → red (151–160). At the cap a &quot;5/5&quot; toast appears and recordings are blocked.</li></ul><h3 id="the-free-tier-has-a-shared-99-user-daily-capacity-pool" tabindex="-1">The free tier has a shared 99-user daily capacity pool <a class="header-anchor" href="#the-free-tier-has-a-shared-99-user-daily-capacity-pool" aria-label="Permalink to &quot;The free tier has a shared 99-user daily capacity pool&quot;">​</a></h3><p>Free users share a 99-user-per-day pool. When the pool is reached, new users see a full-screen capacity overlay; users already active are grandfathered in.</p><ul><li>This caps the maximum daily infrastructure cost, not individual usage — the 99-user pool keeps the service free for everyone.</li><li>Pro users bypass this cap entirely.</li><li>The cap resets at midnight UTC daily.</li></ul><h3 id="recordings-are-15-seconds-free-or-30-seconds-pro" tabindex="-1">Recordings are 15 seconds (free) or 30 seconds (Pro) <a class="header-anchor" href="#recordings-are-15-seconds-free-or-30-seconds-pro" aria-label="Permalink to &quot;Recordings are 15 seconds (free) or 30 seconds (Pro)&quot;">​</a></h3><p>The limit is driven by STT cost structure, which charges per audio second.</p><ul><li>15 seconds captures one complete thought. Longer recordings tend to contain multiple thoughts (better as separate cards) or silence.</li><li>The recording toolbar shows a live countdown timer with the last 3 seconds highlighted in red.</li><li>Uploaded WAV or MP3 files (up to 6 MB) run through the same STT engine with the same length limits. Accuracy depends on file quality, background noise, and accent. Edit the text box or tap reset to try again.</li></ul><h3 id="card-text-is-capped-at-150-characters" tabindex="-1">Card text is capped at 150 characters <a class="header-anchor" href="#card-text-is-capped-at-150-characters" aria-label="Permalink to &quot;Card text is capped at 150 characters&quot;">​</a></h3><p>Shorter messages make better-looking, more shareable cards.</p><ul><li>150 characters fits a thoughtful sentence without overflowing the card canvas. Most stock example phrases fit comfortably.</li><li>The counter turns red and the Done button disables past 150, but the textarea does not block input — you can see what you would lose by shortening.</li><li>An invisible 10-character grace zone (up to 160) prevents cutting a final word like &quot;friend&quot; mid-letter. The card image, transcription, and tone rewriting all use the first 150 characters.</li></ul><h3 id="shared-links-expire-after-7-days-14-for-pro" tabindex="-1">Shared links expire after 7 days (14 for Pro) <a class="header-anchor" href="#shared-links-expire-after-7-days-14-for-pro" aria-label="Permalink to &quot;Shared links expire after 7 days (14 for Pro)&quot;">​</a></h3><p>A daily cleanup cron at midnight UTC removes expired card data.</p><ul><li><strong>Deleted:</strong> card image (Vercel Blob), voice recording (Blob), and metadata sidecar (<code>meta/&lt;id&gt;.json</code>).</li><li><strong>Preserved:</strong> Downloaded images are yours forever. Cards saved to the vault are exempt from cleanup (cross-referenced against the <code>vault_cards</code> Neon table on every cleanup pass).</li></ul><h3 id="we-do-not-run-automated-content-moderation" tabindex="-1">We do not run automated content moderation <a class="header-anchor" href="#we-do-not-run-automated-content-moderation" aria-label="Permalink to &quot;We do not run automated content moderation&quot;">​</a></h3><p>No automated filter exists for card text or voice recordings.</p><ul><li>Daily caps make bulk automated abuse impractical — a script creating 1,000 cards per minute hits the cap in seconds.</li><li>A determined user can create any content. A reporting mechanism is planned but not yet implemented.</li></ul><h3 id="cards-are-available-in-one-size-only-square" tabindex="-1">Cards are available in one size only (square) <a class="header-anchor" href="#cards-are-available-in-one-size-only-square" aria-label="Permalink to &quot;Cards are available in one size only (square)&quot;">​</a></h3><p>We previously offered four sizes (1:1, 9:16, 4:5, 16:9). On mobile, the wider sizes got cropped, the background illustration was cut off, and social media previews were inconsistent. After testing across multiple devices, only the square works reliably on every screen.</p><ul><li>This is a deliberate product decision, not a missing feature.</li></ul><h3 id="vault-storage-is-capped-at-50-cards-for-pro-users" tabindex="-1">Vault storage is capped at 50 cards for Pro users <a class="header-anchor" href="#vault-storage-is-capped-at-50-cards-for-pro-users" aria-label="Permalink to &quot;Vault storage is capped at 50 cards for Pro users&quot;">​</a></h3><p>Pro vault cards are stored server-side in Neon Postgres and persist across sessions. The 50-card limit protects the shared database from bulk abuse.</p><ul><li>Free users&#39; vault data lives in browser localStorage — no cap, but data is lost on browser storage clear.</li><li>The vault shows a count badge (&quot;5/50&quot;) to make the limit visible. Select and delete to stay under the cap.</li></ul><h3 id="audio-uploads-are-limited-to-6-mb-wav-or-mp3-only" tabindex="-1">Audio uploads are limited to 6 MB, WAV or MP3 only <a class="header-anchor" href="#audio-uploads-are-limited-to-6-mb-wav-or-mp3-only" aria-label="Permalink to &quot;Audio uploads are limited to 6 MB, WAV or MP3 only&quot;">​</a></h3><p>Uploaded audio files are validated both client-side and server-side.</p><ul><li>Client validates: MIME type (<code>audio/wav</code>, <code>audio/mpeg</code>, etc.) and file extension (<code>.wav</code>, <code>.mp3</code>).</li><li>Server validates: total size ≤ 6 MB, duration via AudioContext decode.</li><li>Larger files or unsupported formats are rejected with a clear toast message.</li></ul><h3 id="no-user-accounts-—-everything-is-session-based" tabindex="-1">No user accounts — everything is session-based <a class="header-anchor" href="#no-user-accounts-—-everything-is-session-based" aria-label="Permalink to &quot;No user accounts — everything is session-based&quot;">​</a></h3><p>There is no login, no sign-up, and no persistent user identity. A session ID in sessionStorage identifies you for the current browsing session.</p><ul><li>Your recordings, cards, and draft text reset on browser data clear.</li><li>The Pro key (stored in localStorage) is the only persistent identifier — it unlocks vault sync across devices. Without it, everything is ephemeral.</li><li>This is an intentional trade-off: no account friction means instant use, at the cost of cross-device state.</li></ul><h3 id="older-safari-versions-may-show-slightly-different-layouts" tabindex="-1">Older Safari versions may show slightly different layouts <a class="header-anchor" href="#older-safari-versions-may-show-slightly-different-layouts" aria-label="Permalink to &quot;Older Safari versions may show slightly different layouts&quot;">​</a></h3><p>Older Safari versions may show tighter spacing and slightly different card aspect ratios — graceful degradations, not bugs.</p><hr>',36)])])}const m=a(i,[["render",o]]);export{p as __pageData,m as default};
